// 1. Charge Payment Intent (Idempotent)
POST /api/v1/payments
Headers:
  Idempotency-Key: pay_ord_88412_v1
Request:
{
  "merchant_id": "merch_9910",
  "amount_cents": 12999,
  "currency": "USD",
  "payment_method_token": "pm_card_visa_4242"
}
Response (200 OK):
{
  "payment_id": "pay_01HV9X8812",
  "status": "CAPTURED",
  "amount_cents": 12999,
  "currency": "USD",
  "psp_reference_id": "ch_3P9xK2LkdIwHu7ix",
  "ledger_transaction_id": "ldg_tx_991823"
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY payment_intents (PostgreSQL / CockroachDB (ACID)) {
  [PK ] payment_id             UUID
  [IDX] idempotency_key        VARCHAR(128) UNIQUE
        buyer_account_id       UUID
        amount_cents           BIGINT
        status                 ENUM('INIT','CAPTURED','FAILED')
}

ENTITY psp_attempts (PostgreSQL / CockroachDB (ACID)) {
  [PK ] attempt_id             UUID
  [FK ] payment_id             UUID
  [IDX] psp_reference_id       VARCHAR(128)
        psp_name               ENUM('STRIPE','ADYEN')
        raw_response_code      VARCHAR(32)
}

ENTITY ledger_entries (Immutable Append-Only Double-Entry DB) {
  [PK ] entry_id               UUID
  [FK ] payment_id             UUID
  [IDX] account_id             UUID
        direction              ENUM('DEBIT','CREDIT')
        amount_cents           BIGINT (> 0)
}

// Relationships: payment_intents --(1 : N (PSP execution attempts))--> psp_attempts --(1 : 2+ (zero-sum DEBIT/CREDIT))--> ledger_entries

/*
================================================================================
FLOW 1: IDEMPOTENT EXECUTION WITHOUT HOLDING DB CONNECTIONS ACROSS PSP HTTP CALL
================================================================================
[Client] -> POST /payments (Idempotency-Key: K1)
   |-- [DB Tx 1 (5ms)] : Claim K1 + Insert PaymentOrder(id=PO_99, status=EXECUTING) -> COMMIT
   |-- [HTTP Call (800ms, NO DB LOCK)] : Call PSP.charge(idempotencyKey=PO_99, cents=10000)
   |-- [DB Tx 2 (5ms)] : Update PaymentOrder(status=CAPTURED) + Insert OutboxEvent -> COMMIT

================================================================================
FLOW 2: DOUBLE-ENTRY LEDGER POSTING & INVARIANT CHECK
================================================================================
Kafka(PaymentCaptured: PO_99, $100.00, Fee: $3.00) -> [LedgerService]
   |-- Entry 1: DEBIT  acct=PSP_RECEIVABLE      +10000 cents
   |-- Entry 2: CREDIT acct=MERCHANT_PAYABLE    + 9700 cents
   |-- Entry 3: CREDIT acct=PLATFORM_FEE_REV    +  300 cents
   |-- Assert: Total Debits (10000) == Total Credits (9700 + 300) -> COMMIT
*/

package com.sdi.payment.service;

import com.sdi.payment.domain.*;
import java.time.Instant;
import java.util.*;

public class PaymentOrchestrationEngine {

    private final PaymentRepository paymentRepo;
    private final PspGatewayClient pspClient;

    public PaymentOrchestrationEngine(PaymentRepository paymentRepo, PspGatewayClient pspClient) {
        this.paymentRepo = paymentRepo;
        this.pspClient = pspClient;
    }

    /**
     * FLOW 1: Safe Idempotent Payment Execution (Zero DB Locks Held During Network I/O)
     */
    public PaymentOrderEntity executePayment(
        String idempotencyKey,
        long buyerId,
        long sellerId,
        long amountCents,
        String currency,
        String paymentToken
    ) {
        // STEP 1: Short ACID Transaction #1 - Claim Idempotency Key & Persist EXECUTING Order
        PaymentOrderEntity order = paymentRepo.executeInTransaction(tx -> {
            Optional<PaymentOrderEntity> existing = tx.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                return existing.get(); // Idempotent replay!
            }
            String orderId = "po_" + UUID.randomUUID().toString().replace("-", "");
            return tx.insertExecutingOrder(idempotencyKey, orderId, buyerId, sellerId, amountCents, currency);
        });

        // If already terminal from a prior completed request, return immediately
        if (order.status() == PaymentOrderStatus.CAPTURED || order.status() == PaymentOrderStatus.FAILED) {
            return order;
        }

        // STEP 2: Call External PSP OUTSIDE any DB transaction (pass orderId as PSP Idempotency Key)
        PspChargeResult pspResult = pspClient.chargeWithRetry(
            order.paymentOrderId(), // Ensures PSP never double-charges on network timeout
            amountCents,
            currency,
            paymentToken
        );

        // STEP 3: Short ACID Transaction #2 - Advance State Machine & Write Transactional Outbox
        return paymentRepo.executeInTransaction(tx -> {
            PaymentOrderStatus nextStatus = pspResult.isSuccess()
                ? PaymentOrderStatus.CAPTURED
                : PaymentOrderStatus.FAILED;

            PaymentOrderEntity updated = tx.transitionOrderStatus(
                order.paymentOrderId(),
                PaymentOrderStatus.EXECUTING,
                nextStatus,
                pspResult.pspReference()
            );

            if (nextStatus == PaymentOrderStatus.CAPTURED) {
                tx.insertOutboxEvent("PAYMENT_CAPTURED", updated.paymentOrderId(), updated);
            }
            return updated;
        });
    }

    /**
     * FLOW 2: Immutable Double-Entry Ledger Recording with Zero-Sum Balance Assertion
     */
    public void postDoubleEntryLedger(
        LedgerRepository ledgerRepo,
        String paymentOrderId,
        long grossCents,
        long platformFeeCents,
        String currency,
        long sellerId
    ) {
        long merchantNetCents = grossCents - platformFeeCents;
        String ledgerTxId = "ltx_" + paymentOrderId; // Deterministic for idempotency

        List<LedgerEntryEntity> entries = List.of(
            new LedgerEntryEntity(
                UUID.randomUUID(), ledgerTxId, paymentOrderId,
                "ACCT_PSP_RECEIVABLE", EntryDirection.DEBIT, grossCents, currency, Instant.now()
            ),
            new LedgerEntryEntity(
                UUID.randomUUID(), ledgerTxId, paymentOrderId,
                "ACCT_MERCHANT_PAYABLE_" + sellerId, EntryDirection.CREDIT, merchantNetCents, currency, Instant.now()
            ),
            new LedgerEntryEntity(
                UUID.randomUUID(), ledgerTxId, paymentOrderId,
                "ACCT_PLATFORM_FEE_REVENUE", EntryDirection.CREDIT, platformFeeCents, currency, Instant.now()
            )
        );

        // Enforce fundamental Double-Entry Accounting invariant: SUM(DEBIT) == SUM(CREDIT)
        long totalDebits = entries.stream()
            .filter(e -> e.direction() == EntryDirection.DEBIT)
            .mapToLong(LedgerEntryEntity::amountCents).sum();
        long totalCredits = entries.stream()
            .filter(e -> e.direction() == EntryDirection.CREDIT)
            .mapToLong(LedgerEntryEntity::amountCents).sum();

        if (totalDebits != totalCredits) {
            throw new IllegalStateException(
                "Unbalanced ledger transaction! Debits=" + totalDebits + ", Credits=" + totalCredits
            );
        }

        ledgerRepo.insertBalancedEntriesIdempotent(ledgerTxId, paymentOrderId, entries);
    }
}
